import os

IMG0 = "/home/ctfplayer/ctf_files/disk.img0"
IMG1 = "/home/ctfplayer/ctf_files/disk.img1"
BLOCK_SIZE = 512
NUM_BLOCKS = 128

def bitwise_inverse(block):
    return bytes([~b & 0xFF for b in block])

def compare_blocks():
    table = []
    with open(IMG0, "rb") as f0, open(IMG1, "rb") as f1:
        for i in range(NUM_BLOCKS):
            f0.seek(i * BLOCK_SIZE)
            f1.seek(i * BLOCK_SIZE)
            b0 = f0.read(BLOCK_SIZE)
            b1 = f1.read(BLOCK_SIZE)
            if b0 == b1:
                result = "identical"
            elif b0 == bitwise_inverse(b1):
                result = "inverse"
            else:
                result = "differ"
            table.append({
                'block': i,
                'img0_digest': b0[:8].hex(),
                'img1_digest': b1[:8].hex(),
                'result': result
            })
    return table

def print_summary(table):
    print(f"{'Block':>5} {'img0_digest':>18} {'img1_digest':>18} {'Relation':>10}")
    for entry in table:
        print(f"{entry['block']:5d} {entry['img0_digest']:>18} {entry['img1_digest']:>18} {entry['result']:>10}")

    identical = sum(1 for entry in table if entry['result'] == 'identical')
    inverse = sum(1 for entry in table if entry['result'] == 'inverse')
    differ = sum(1 for entry in table if entry['result'] == 'differ')
    print(f"\nIdentical: {identical}, Inverse: {inverse}, Differ: {differ}")

    print("\nPattern by block:")
    print(' '.join(entry['result'][0].upper() for entry in table))

def main():
    table = compare_blocks()
    print_summary(table)

if __name__ == "__main__":
    main()
